using System;
using System.Data;
using System.IO;
using iTextSharp.text;
using iTextSharp.text.pdf;

namespace InformationWeb.Controls.Graduation
{
    public static class GraduationBangTotNghiepPdfFiller
    {
        #region Cấu hình mẫu -- căn tạm dùng cahcs này . vì field mẫu gốc kéo thả không khớp với file repx

        public const string PDF_TEMPLATE_FILE = "Graduation_BangTotNghiep_SC2_2.pdf";

        private const float PAGE_WIDTH_DX = 827F;
        private const float PAGE_HEIGHT_DX = 583F;

        private const float REPX_MARGIN_LEFT = 25F;
        private const float REPX_MARGIN_TOP = 1F;

        private const float REPX_LABEL_PADDING_LEFT = 2F;
        private const float REPX_LABEL_PADDING_RIGHT = 2F;
        //Lấy số liệu từng ô trong file repx
        private static readonly PdfTextField[] DetailFields = new PdfTextField[]
        {
            FieldText("StudentFullName", 232.7083F, 240.8749F, 335.7914F, 24.99998F, 13F, true),
            FieldText("BirthDateText", 647.0836F, 241.8749F, 142.208F, 25.00002F, 13F, false),
            FieldText("PersonID", 243.7083F, 277.1667F, 397.9167F, 23F, 13F, false),
            FieldText("SpecialBranchShortName", 501.4582F, 309.25F, 287.8333F, 23F, 13F, false),
            FieldText("DayOfCourse", 213.7503F, 339.3334F, 83.33331F, 23F, 13F, false),
            FieldDate("StartAt", "dd/MM/yyyy", 383.8751F, 337.3334F, 105.9999F, 25F, 13F, false),
            FieldDate("FinishAt", "dd/MM/yyyy", 573.9167F, 337.3334F, 113.1246F, 25F, 13F, false),
            FieldText("CerNo", 289.0419F, 178.875F, 327.2498F, 22.99998F, 13F, false),
            FieldDate("Signingdate", "dd", "Signingdate_Day", 530.875F, 391.75F, 43.75F, 25.00009F, 13F, false),
            FieldDate("Signingdate", "MM", "Signingdate_Month", 606.1666F, 391.75F, 43.75F, 25.00009F, 13F, false),
            FieldDate("Signingdate", "yyyy", "Signingdate_Year", 668.4999F, 391.7499F, 88.20819F, 25F, 13F, false)
        };

        //các trường cố định tạm tách riêng ra đỡ nhầm
        private const bool DRAW_STATIC_LABELS = true;

        private static readonly PdfStaticField[] StaticFields = new PdfStaticField[]
        {
            Static("Trường Cao đẳng nghề số 21", 183.7083F, 370.75F, 238.5417F, 25F, 14F, false),
            Static("Gia Lai,", 425.1665F, 393.6251F, 73.95834F, 25F, 13F, false)
        };

        #endregion

        #region Xuất PDF

        public static void FillDetailPdf(string templatePath, string outputPath, DataRow drw)
        {
            if (!File.Exists(templatePath))
            {
                throw new FileNotFoundException(
                    String.Format("Không tìm thấy PDF mẫu: {0}. Đặt file tại Template/MauPDF/.", templatePath),
                    templatePath);
            }

            string strDir = Path.GetDirectoryName(outputPath);
            if (!string.IsNullOrEmpty(strDir) && !Directory.Exists(strDir))
                Directory.CreateDirectory(strDir);

            PdfReader reader = null;
            FileStream fs = null;
            PdfStamper stamper = null;

            try
            {
                reader = new PdfReader(templatePath);
                fs = new FileStream(outputPath, FileMode.Create, FileAccess.Write);
                stamper = new PdfStamper(reader, fs);

                AcroFields form = stamper.AcroFields;
                bool hasAcroForm = form != null && form.Fields != null && form.Fields.Count > 0;
                if (hasAcroForm)
                    FillAcroForm(form, drw);

                DrawOverlay(stamper, reader, drw, hasAcroForm);

                stamper.FormFlattening = true;
            }
            finally
            {
                if (stamper != null) stamper.Close();
                if (reader != null) reader.Close();
                if (fs != null) fs.Dispose();
            }
        }

        private static void FillAcroForm(AcroFields form, DataRow drw)
        {
            int i;
            for (i = 0; i < DetailFields.Length; i++)
            {
                PdfTextField item = DetailFields[i];
                if (string.IsNullOrEmpty(item.AcroFieldName))
                    continue;
                if (!form.Fields.ContainsKey(item.AcroFieldName))
                    continue;

                string strValue;
                if (item.IsDate)
                    strValue = Convert.ToDateTime(drw[item.ColumnName]).ToString(item.DateFormat);
                else
                    strValue = drw[item.ColumnName].ToString().Trim();

                form.SetField(item.AcroFieldName, strValue);
            }
        }

        private static void DrawOverlay(PdfStamper stamper, PdfReader reader, DataRow drw, bool skipDynamicFields)
        {
            BaseFont fontRegular = CreateUnicodeFont(false);
            BaseFont fontBold = CreateUnicodeFont(true);
            PdfContentByte canvas = stamper.GetOverContent(1);
            Rectangle pageSize = reader.GetPageSizeWithRotation(1);

            if (DRAW_STATIC_LABELS)
            {
                int j;
                for (j = 0; j < StaticFields.Length; j++)
                {
                    PdfStaticField staticItem = StaticFields[j];
                    DrawTextInRect(canvas, pageSize, staticItem.Text, staticItem.X, staticItem.Y,
                        staticItem.Width, staticItem.Height, staticItem.FontSize, staticItem.Bold, fontRegular, fontBold);
                }
            }

            if (skipDynamicFields)
                return;

            int i;
            for (i = 0; i < DetailFields.Length; i++)
            {
                PdfTextField item = DetailFields[i];
                string strValue;
                if (item.IsDate)
                    strValue = Convert.ToDateTime(drw[item.ColumnName]).ToString(item.DateFormat);
                else
                    strValue = drw[item.ColumnName].ToString().Trim();

                DrawTextInRect(canvas, pageSize, strValue, item.X, item.Y, item.Width, item.Height,
                    item.FontSize, item.Bold, fontRegular, fontBold);
            }
        }

        private static void DrawTextInRect(PdfContentByte canvas, Rectangle pageSize, string strValue,
            float x, float y, float width, float height, float fontSize, bool bold,
            BaseFont fontRegular, BaseFont fontBold)
        {
            BaseFont baseFont = bold ? fontBold : fontRegular;
            Rectangle rect = ToLabelRect(x, y, width, height, pageSize);
            ColumnText ct = new ColumnText(canvas);

            ct.SetSimpleColumn(
                new Phrase(strValue, new Font(baseFont, fontSize)),
                rect.Left, rect.Bottom, rect.Right, rect.Top,
                fontSize, Element.ALIGN_LEFT);
            ct.Go();
        }

        #endregion

        #region Chuyển tọa độ

        private static Rectangle ToLabelRect(float x, float y, float width, float height, Rectangle pageSize)
        {
            float pageWidthPt = pageSize.Width;
            float pageHeightPt = pageSize.Height;
            float expectedWidthPt = PAGE_WIDTH_DX / 100F * 72F;
            float expectedHeightPt = PAGE_HEIGHT_DX / 100F * 72F;
            float scaleX = pageWidthPt / expectedWidthPt;
            float scaleY = pageHeightPt / expectedHeightPt;

            float absX = REPX_MARGIN_LEFT + x;
            float absY = REPX_MARGIN_TOP + y;

            float leftDx = absX + REPX_LABEL_PADDING_LEFT;
            float rightDx = absX + width - REPX_LABEL_PADDING_RIGHT;
            float topDx = absY;
            float bottomDx = absY + height;

            float left = DxToPoint(leftDx, scaleX);
            float right = DxToPoint(rightDx, scaleX);
            float top = pageHeightPt - DxToPoint(topDx, scaleY);
            float bottom = pageHeightPt - DxToPoint(bottomDx, scaleY);

            return new Rectangle(left, bottom, right, top);
        }

        private static float DxToPoint(float valueDx, float scale)
        {
            return valueDx / 100F * 72F * scale;
        }

        private static BaseFont CreateUnicodeFont(bool bold)
        {
            string strFontFile = bold ? "timesbd.ttf" : "times.ttf";
            string strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), strFontFile);
            if (!File.Exists(strFontPath))
                strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), "arial.ttf");
            if (!File.Exists(strFontPath))
                return BaseFont.CreateFont(BaseFont.HELVETICA, BaseFont.CP1252, BaseFont.NOT_EMBEDDED);

            return BaseFont.CreateFont(strFontPath, BaseFont.IDENTITY_H, BaseFont.EMBEDDED);
        }

        #endregion

        #region Helper

        private sealed class PdfTextField
        {
            public string AcroFieldName;
            public string ColumnName;
            public string DateFormat;
            public bool IsDate;
            public float X;
            public float Y;
            public float Width;
            public float Height;
            public float FontSize;
            public bool Bold;
        }

        private static PdfTextField FieldText(string name, float x, float y, float w, float h, float fontSize, bool bold)
        {
            PdfTextField item = new PdfTextField();
            item.AcroFieldName = name;
            item.ColumnName = name;
            item.IsDate = false;
            item.X = x;
            item.Y = y;
            item.Width = w;
            item.Height = h;
            item.FontSize = fontSize;
            item.Bold = bold;
            return item;
        }

        private static PdfTextField FieldDate(string columnName, string dateFormat, float x, float y, float w, float h, float fontSize, bool bold)
        {
            PdfTextField item = new PdfTextField();
            item.AcroFieldName = columnName;
            item.ColumnName = columnName;
            item.DateFormat = dateFormat;
            item.IsDate = true;
            item.X = x;
            item.Y = y;
            item.Width = w;
            item.Height = h;
            item.FontSize = fontSize;
            item.Bold = bold;
            return item;
        }

        private static PdfTextField FieldDate(string columnName, string dateFormat, string acroName, float x, float y, float w, float h, float fontSize, bool bold)
        {
            PdfTextField item = FieldDate(columnName, dateFormat, x, y, w, h, fontSize, bold);
            item.AcroFieldName = acroName;
            return item;
        }

        private static PdfStaticField Static(string text, float x, float y, float w, float h, float fontSize, bool bold)
        {
            PdfStaticField item = new PdfStaticField();
            item.Text = text;
            item.X = x;
            item.Y = y;
            item.Width = w;
            item.Height = h;
            item.FontSize = fontSize;
            item.Bold = bold;
            return item;
        }

        private sealed class PdfStaticField
        {
            public string Text;
            public float X;
            public float Y;
            public float Width;
            public float Height;
            public float FontSize;
            public bool Bold;
        }

        #endregion
    }
}

